def _matrix_pair_support(data: dict[str, np.ndarray], mode_table, expected: tuple[int, int]) -> tuple[np.ndarray, np.ndarray]:
    """Return the mode-pair support and weight the matrix blocks must consume.

    The support and weight come from the pair policy produced with the FOURIN
    coefficients, so the matrix stage retains exactly the mode pairs that the
    coefficient stage projected, cross-``n`` pairs included, with the same
    reduced 3-D normalization.  When a caller supplies coefficients without a
    pair policy the matrix stage stays neutral and retains every pair of the
    mode table: the coefficient tensors already carry the pair policy, so
    unrepresented pairs remain zero without a second mask here.
    """

    policy = data.get("pair_policy") or {}
    neutral = np.ones((mode_table.size, mode_table.size), dtype=float)
    if "matrix_active" in policy:
        support = np.asarray(policy["matrix_active"], dtype=float)
    elif "active_pairs" in policy:
        support = np.asarray(policy["active_pairs"], dtype=float)
    else:
        support = neutral
    if "matrix_weight" in policy:
        weight = np.asarray(policy["matrix_weight"], dtype=float)
    else:
        weight = neutral
    if support.shape != expected:
        raise ValueError(f"matrix pair support must have shape {expected}, got {support.shape}.")
    if weight.shape != expected:
        raise ValueError(f"matrix pair weight must have shape {expected}, got {weight.shape}.")
    return support, weight

