def cross_n_mask(mode_table) -> np.ndarray:
    return mode_table.n[:, None] != mode_table.n[None, :]


def _energy_pair_support(coeffs, mode_table) -> np.ndarray:
    """Return the mode-pair support that the energy accounting must respect.

    The energy stage reads the pair policy carried by the FOURIN coefficients so
    that coefficient projection, matrix assembly and energy accounting agree on
    the retained mode pairs.  Pairs the policy never activated contribute no
    energy, in either the same-``n`` or the cross-``n`` channel.
    """

    if coeffs is None:
        data: dict = {}
    elif hasattr(coeffs, "as_legacy_dict"):
        data = coeffs.as_legacy_dict()
    else:
        data = dict(coeffs)
    policy = data.get("pair_policy") or {}
    expected = (mode_table.size, mode_table.size)
    for key in ("matrix_active", "active_pairs"):
        if key in policy:
            support = np.asarray(policy[key])
            if support.shape != expected:
                raise ValueError(f"pair policy {key} must have shape {expected}, got {support.shape}.")
            return support.astype(bool)
    return np.ones(expected, dtype=bool)


def block_cross_norm(block: np.ndarray, mode_table) -> float:
    mask = cross_n_mask(mode_table)
    arr = np.asarray(block, dtype=float)
    if arr.ndim != 3:
        raise ValueError("block must be rank-3.")
    return float(np.linalg.norm(arr[mask, :]))


def summarize_energy_path(coeffs, potential, kinetic, radial_grid, mode_table) -> dict[str, float]:
    """Return compact energy-level diagnostics from the same assembled blocks."""

    support = _energy_pair_support(coeffs, mode_table)
    mask = cross_n_mask(mode_table) & support
    same_mask = (~cross_n_mask(mode_table)) & support
    ai = np.asarray(potential.AI, dtype=float)
    bd = np.asarray(kinetic.BD, dtype=float)
    cc = np.asarray(potential.CC, dtype=float)
    for name, block in (("AI", ai), ("CC", cc), ("BD", bd)):
        if block.shape[:2] != support.shape or block.shape[2] != radial_grid.n_intervals:
            raise ValueError(
                f"{name} must have shape {(*support.shape, radial_grid.n_intervals)}, got {block.shape}."
            )

